#include "crypto.h"
#include <stdio.h>

/*
 * Reference: the inputs and outputs of message encryption.
 *
 * message (plaintext) is the original text as bytes, passed to crypto_encrypt().
 * message_len counts the bytes without the terminating '\0'. sizeof(message)
 * includes that terminator, so we subtract 1 for this string.
 *
 * key is a secret 32-byte key (CRYPTO_KEY_SIZE), generated by
 * crypto_generate_key() after successful crypto_init(). The sender encrypts
 * and the recipient decrypts using the same key. Both roles run in one program
 * in this demo; securely establishing a shared key is a separate task in a real
 * application. Do not publish the key.
 *
 * nonce is a public 12-byte value (CRYPTO_NONCE_SIZE) that must never be reused
 * for encryption with the same key. It is not a second key. The recipient needs
 * the exact nonce used for encryption. Here, randombytes_buf() fills it for one
 * message with a fresh key. For many messages with one key, use a managed nonce
 * counter.
 *
 * aad (Additional Authenticated Data) is extra public data, such as a protocol
 * version and message number. It is not encrypted, but is authenticated by the
 * tag along with the message. Decryption requires the same AAD bytes.
 * aad_len is its length. If there is no AAD, pass NULL and 0.
 *
 * ciphertext contains encrypted bytes followed by an authentication tag
 * (combined mode). Libsodium appends the 16-byte tag (CRYPTO_TAG_SIZE), which
 * detects message tampering or a mismatched key, nonce or AAD. The required
 * buffer size is message_len + CRYPTO_TAG_SIZE. Our function does not include
 * the nonce or AAD in this buffer: the protocol must transmit or reconstruct
 * them separately. Ciphertext is binary data: display it as hex, not with %s.
 *
 * capacity is the allocated output buffer's size in bytes.
 * ciphertext_len is the actual output length. Pass &ciphertext_len so the
 * function can write the length into the caller's variable.
 *
 * decrypted is the recovered message buffer; decrypted_len is its length.
 * Use the data only after successful crypto_decrypt(). To print it with %s,
 * allocate one extra byte and append '\0' after the message: decryption does
 * not automatically turn the bytes into a C string.
 *
 * status is the return code: GDEV_CRYPTO_OK means success. Handle errors
 * without treating the output as a valid message. Authentication does not
 * prevent replay of the same packet: replay protection is implemented
 * separately at the protocol level.
 */


static int prepare_crypto(unsigned char key[CRYPTO_KEY_SIZE],
    unsigned char nonce[CRYPTO_NONCE_SIZE]) {

    int status = crypto_init();
    if (status != GDEV_CRYPTO_OK) {
        fprintf(stderr, "Failed to initialize crypto library: %d\n", status);
        return status;
    }

    status = crypto_generate_key(key);
    if (status != GDEV_CRYPTO_OK) {
        fprintf(stderr, "Failed to generate key: %d\n", status);
        return status;
    }

    // Array parameters are pointers: sizeof(nonce) would give the pointer size.
    randombytes_buf(nonce, CRYPTO_NONCE_SIZE);
    return GDEV_CRYPTO_OK;
}

static void print_message(const unsigned char *message, size_t message_len) {
    printf("Message: ");
    // Print exactly the supplied bytes; no terminating '\0' is required.
    fwrite(message, 1, message_len, stdout);
    printf("\nMessage length: %zu bytes\n", message_len);
}

static void print_ciphertext(const unsigned char *ciphertext, size_t ciphertext_len) {
    printf("Encrypted message length: %zu bytes\n", ciphertext_len);
    printf("Ciphertext (hex): ");
    for (size_t i = 0; i < ciphertext_len; i++) {
        // Each byte is displayed as two hexadecimal digits.
        printf("%02x ", (unsigned int)ciphertext[i]);
    }
    printf("\n");
}

int main(void) {
    const unsigned char message[] = {
        "Hello! Let`s meet at the park at 5pm."
    };

    const size_t message_len = sizeof(message) - 1; // Exclude null terminator

    unsigned char key[CRYPTO_KEY_SIZE];
    unsigned char nonce[CRYPTO_NONCE_SIZE];

    int status = prepare_crypto(key, nonce);
    if (status != GDEV_CRYPTO_OK) {
        return 1;
    }
    printf("Generated a secret key and nonce for encryption.\n");

    const unsigned char aad[] = "message-to-friend:v1"; // Example Additional Authenticated Data
    const size_t aad_len = sizeof(aad) - 1; // Exclude null terminator

    unsigned char ciphertext[sizeof(message) - 1 + CRYPTO_TAG_SIZE];
    size_t ciphertext_len = 0;

    print_message(message, message_len);

    status = crypto_encrypt(
        ciphertext,
        sizeof(ciphertext),
        &ciphertext_len,
        message,
        message_len,
        aad,
        aad_len,
        nonce,
        key
    );
    if (status != GDEV_CRYPTO_OK) {
        fprintf(stderr, "Encryption failed: %d\n", status);
        return 1;
    }

    print_ciphertext(ciphertext, ciphertext_len);

    unsigned char decrypted[sizeof(message) - 1];
    size_t decrypted_len = 0;


    status = crypto_decrypt(
        decrypted,
        sizeof(decrypted),
        &decrypted_len,
        ciphertext,
        ciphertext_len,
        aad,
        aad_len,
        nonce,
        key
    );
    if (status != GDEV_CRYPTO_OK) {
        fprintf(stderr, "Decryption failed: %d\n", status);
        return 1;

    }
    printf("\nRecipient: authentication succeeded\n");
    print_message(decrypted, decrypted_len);

    return 0;
}
